head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS70060";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — DST_URL

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70060.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70060.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldods70060: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_goViewer (조건 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70060.btn_window_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goViewer
 * @description go Viewer 처리
 * @param {*} acptNo acptNo
 * @returns {void}
 * @hidden N
 */
scwin.goViewer = function (acptNo) {
    fn_examViewer((String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? "")))), acptNo);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_examViewer — as-is 정의 없음(원본 JS 미제공 — 회신)
};
